@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/newsreader/opsz-italic.css";
@import "@fontsource-variable/inter";

/* Light (faithful): butter-cream page #fef9ef, midnight ink #2a2b2f, terracotta #b05a36 for
   buttons, checks and the italic accent words. White cards on sandy #d1c9bf hairlines; outline
   pills on a paler #e1e1df. A very light neutral panel #f8f7f5 for the split band. */
:root {
  --background: #fef9ef;
  --foreground: #2a2b2f;
  --card: #ffffff;
  --card-foreground: #2a2b2f;
  --popover: #ffffff;
  --popover-foreground: #2a2b2f;
  --primary: #b05a36;
  --primary-foreground: #fef9ef;
  --secondary: #f5eee1;
  --secondary-foreground: #2a2b2f;
  --muted: #f8f7f5;
  --muted-foreground: #616867;
  --accent: #f5eee1;
  --accent-foreground: #2a2b2f;
  --destructive: #c0392b;
  --destructive-foreground: #ffffff;
  --border: #d1c9bf;
  --input: #e1e1df;
  --ring: #b05a36;
  --highlight: #b05a36;
  --highlight-foreground: #fef9ef;
  --glow: #d99a74;
  --chart-1: #b05a36;
  --chart-2: #a9d3e9;
  --chart-3: #2a2b2f;
  --chart-4: #b0afab;
  --chart-5: #d1c9bf;
  --sidebar: #f5eee1;
  --sidebar-foreground: #2a2b2f;
  --sidebar-primary: #b05a36;
  --sidebar-primary-foreground: #fef9ef;
  --sidebar-accent: #ffffff;
  --sidebar-accent-foreground: #2a2b2f;
  --sidebar-border: #d1c9bf;
  --sidebar-ring: #b05a36;

  --typeface-body: "Inter Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Newsreader Variable", Georgia, "Times New Roman", serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  /* the original's 1260px content column */
  --page-width: 78.75rem;
  --page-gutter: 1.25rem;
  /* desktop section padding; blocks use half of it on phones */
  --section-y: 6.25rem;
}

/* Dark sibling: the original's midnight bands. Midnight page #2a2b2f, cream ink #fef9ef,
   slightly lifted cards, warm grey hairlines #7c7a74, the same terracotta. */
.dark {
  --background: #2a2b2f;
  --foreground: #fef9ef;
  --card: #333438;
  --card-foreground: #fef9ef;
  --popover: #333438;
  --popover-foreground: #fef9ef;
  --primary: #b05a36;
  --primary-foreground: #fef9ef;
  --secondary: #3a3a3c;
  --secondary-foreground: #fef9ef;
  --muted: #303135;
  --muted-foreground: #b0afab;
  --accent: #3a3a3c;
  --accent-foreground: #fef9ef;
  --destructive: #e0644f;
  --destructive-foreground: #ffffff;
  --border: #7c7a74;
  --input: #5c5b58;
  --ring: #d0805c;
  --highlight: #d0805c;
  --highlight-foreground: #2a2b2f;
  --glow: #d99a74;
  --chart-1: #d0805c;
  --chart-2: #a9d3e9;
  --chart-3: #fef9ef;
  --chart-4: #b0afab;
  --chart-5: #7c7a74;
  --sidebar: #252629;
  --sidebar-foreground: #fef9ef;
  --sidebar-primary: #b05a36;
  --sidebar-primary-foreground: #fef9ef;
  --sidebar-accent: #333438;
  --sidebar-accent-foreground: #fef9ef;
  --sidebar-border: #7c7a74;
  --sidebar-ring: #d0805c;
}
